// Formatear mensaje de recordatorio con un solo botón de confirmación
const order = $input.first().json;
const nombre = order.guest_name || 'amigo/a';
const edad = order.cart_age_days || 1;
const total = Number(order.total_amount) || 0;
const prePedido = order.order_data?.items || [];

// Determinar nivel de urgencia según la edad del carrito
let urgencia = '';
let emoji = '';
let titulo = '';
let mensaje_principal = '';

if (edad === 1) {
  urgencia = 'urgente';
  emoji = '🔥';
  titulo = '¡ÚLTIMA OPORTUNIDAD!';
  mensaje_principal = 'Tu carrito tiene productos esperándote';
} else if (edad === 2) {
  urgencia = 'alta';
  emoji = '⚠️';
  titulo = '¡No olvides tu pedido!';
  mensaje_principal = 'Tu carrito sigue esperándote';
} else if (edad === 3) {
  urgencia = 'media';
  emoji = '💡';
  titulo = '¿Aún quieres tus productos?';
  mensaje_principal = 'Tu carrito sigue esperando tu confirmación';
} else if (edad === 5) {
  urgencia = 'media';
  emoji = '💡';
  titulo = 'Tu carrito sigue esperando';
  mensaje_principal = '¿Ya tomaste tu decisión?';
} else {
  urgencia = 'baja';
  emoji = '🎁';
  titulo = '¡Oferta especial para ti!';
  mensaje_principal = 'Tu carrito tiene descuentos disponibles';
}

// Formatear lista de productos
let productosTexto = '';
if (Array.isArray(prePedido) && prePedido.length > 0) {
  productosTexto = prePedido.map((item, i) => {
    const nombre = item.productName || item.producto_nombre || 'Producto';
    const precio = Number(item.price) || Number(item.precio) || 0;
    const cantidad = item.quantity || item.cantidad || 1;
    return `• ${nombre} x${cantidad} - $${precio.toLocaleString('es-CO')}`;
  }).join('\n');
} else {
  productosTexto = '• Tus productos favoritos están listos';
}

// Calcular día de entrega
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Dom, 1=Lun, etc.
let proximaEntrega = 'Martes';
if (dayOfWeek >= 2 && dayOfWeek <= 4) {
  proximaEntrega = 'Viernes';
} else {
  proximaEntrega = 'Martes';
}

const mensaje = `${emoji} ${titulo}\n\nHola ${nombre},\n\n${mensaje_principal}:\n\n${productosTexto}\n\n💰 *Total: $${total.toLocaleString('es-CO')}*\n\n🚚 Te podemos entregar el *${proximaEntrega}*\n\n${urgencia.toUpperCase()}: ¿Deseas confirmar este pedido?`;

return {
  json: {
    orderId: order.id,
    nombre: nombre,
    telefono: order.guest_phone,
    email: order.guest_email,
    mensaje: mensaje,
    totalCarrito: total,
    cartAge: edad,
    urgencia: urgencia,
    productos: prePedido,
    proximaEntrega: proximaEntrega
  }
};

