// Crear registro de recordatorio en tabla recordatorios_enviados
const order = $('📝 Formatear Mensaje').first().json;
const whatsappSent = $('✅ Actualizar WhatsApp Sent').first().json;

const mensajeResumen = order.mensaje.substring(0, 200) + '...';

return {
  json: {
    cliente_telefono: order.telefono,
    cliente_email: order.email,
    cliente_nombre: order.nombre,
    tipo: 'carrito_abandonado_whatsapp',
    pedido_id: order.orderId,
    mensaje_enviado: mensajeResumen,
    metadata: {
      total: order.totalCarrito,
      cart_age: order.cartAge,
      urgencia: order.urgencia,
      productos_count: order.productos.length,
      whatsapp_sent: whatsappSent.abandoned_whatsapp_sent
    },
    sent_at: new Date().toISOString()
  }
};

// Crear métricas para dashboard
const order = $('📝 Formatear Mensaje').first().json;
const whatsappSent = $('✅ Actualizar WhatsApp Sent').first().json;

return {
  json: {
    order_id: order.orderId,
    status: whatsappSent.abandoned_whatsapp_sent ? 'enviado' : 'error',
    telefono: order.telefono,
    email: order.email,
    cart_age: order.cartAge,
    urgencia: order.urgencia,
    total: order.totalCarrito,
    productos: order.productos.length,
    proxima_entrega: order.proximaEntrega,
    timestamp: new Date().toISOString()
  }
};
